            v = $0; sub(/^[[:space:]]+roles:[[:space:]]*/, "", v); v = trim(v)
            if (v ~ /\[/) {
                gsub(/^\[|\]$/, "", v); gsub(/[[:space:]]/, "", v)
                roles[in_sec] = v
